CREATE TABLE public.random_profile_images (
    id uuid PRIMARY KEY,
    png bytea NOT NULL CHECK (octet_length(png) BETWEEN 8 AND 2097152 AND substring(png FOR 8) = decode('89504e470d0a1a0a', 'hex'))
);
COMMENT ON TABLE public.random_profile_images IS '通过检查的不可变系统头像展示图，保留已发出素材的可读地址';
COMMENT ON COLUMN public.random_profile_images.id IS '不可变图片随机标识';
COMMENT ON COLUMN public.random_profile_images.png IS '已检查并规范化的PNG展示图';

CREATE TABLE public.random_profile_avatars (
    id uuid PRIMARY KEY,
    name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),
    image_id uuid NOT NULL REFERENCES public.random_profile_images(id),
    enabled boolean NOT NULL,
    version bigint NOT NULL CHECK (version > 0),
    updated_at timestamptz NOT NULL
);
COMMENT ON TABLE public.random_profile_avatars IS '管理端维护的系统随机头像池';
COMMENT ON COLUMN public.random_profile_avatars.id IS '头像素材随机标识';
COMMENT ON COLUMN public.random_profile_avatars.name IS '后台素材名称';
COMMENT ON COLUMN public.random_profile_avatars.image_id IS '当前通过检查的不可变展示图片';
COMMENT ON COLUMN public.random_profile_avatars.enabled IS '是否参与新抽取';
COMMENT ON COLUMN public.random_profile_avatars.version IS '素材维护乐观版本';
COMMENT ON COLUMN public.random_profile_avatars.updated_at IS '素材最近更新时间';

CREATE TABLE public.random_profile_words (
    id uuid PRIMARY KEY,
    kind text NOT NULL CHECK (kind IN ('adjective', 'noun')),
    text text NOT NULL CHECK (char_length(text) BETWEEN 1 AND 38),
    enabled boolean NOT NULL,
    version bigint NOT NULL CHECK (version > 0),
    updated_at timestamptz NOT NULL,
    UNIQUE (kind, text)
);
COMMENT ON TABLE public.random_profile_words IS '管理端维护的随机昵称形容词和名词池';
COMMENT ON COLUMN public.random_profile_words.id IS '词条随机标识';
COMMENT ON COLUMN public.random_profile_words.kind IS '词条种类，形容词或名词';
COMMENT ON COLUMN public.random_profile_words.text IS '用于拼接的词条文本';
COMMENT ON COLUMN public.random_profile_words.enabled IS '是否参与新抽取';
COMMENT ON COLUMN public.random_profile_words.version IS '词条维护乐观版本';
COMMENT ON COLUMN public.random_profile_words.updated_at IS '词条最近更新时间';

CREATE TABLE public.random_profile_actions (
    id uuid PRIMARY KEY,
    actor_id uuid NOT NULL REFERENCES public.admin_accounts(id),
    target_id uuid NOT NULL,
    operation text NOT NULL CHECK (operation IN ('avatar.create', 'avatar.edit', 'avatar.image', 'word.create', 'word.edit')),
    before jsonb NOT NULL,
    after jsonb NOT NULL,
    at timestamptz NOT NULL
);
COMMENT ON TABLE public.random_profile_actions IS '系统随机资料维护审计及命令回执快照';
COMMENT ON COLUMN public.random_profile_actions.id IS '操作审计及命令结果标识';
COMMENT ON COLUMN public.random_profile_actions.actor_id IS '执行操作的管理员';
COMMENT ON COLUMN public.random_profile_actions.target_id IS '被维护的头像素材或词条';
COMMENT ON COLUMN public.random_profile_actions.operation IS '后台维护动作';
COMMENT ON COLUMN public.random_profile_actions.before IS '修改前投影，新建记录为JSON空值';
COMMENT ON COLUMN public.random_profile_actions.after IS '修改后投影';
COMMENT ON COLUMN public.random_profile_actions.at IS '维护提交时间';
CREATE INDEX random_profile_actions_target_idx ON public.random_profile_actions(target_id, at, id);

