DO $$
DECLARE table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY['random_profile_images', 'random_profile_avatars',
        'random_profile_words', 'random_profile_actions'] LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);
        EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', table_name);
        EXECUTE format('CREATE POLICY application_account ON public.%I USING (true) WITH CHECK (true)', table_name);
        EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC', table_name);
    END LOOP;
END $$;
